// GIVEN. Do not edit this file.
namespace DatabasesLab;

/// <summary>One item turned in at the lost and found desk.</summary>
public class FoundItem
{
    /// <summary>The number the database assigned: 1, 2, 3, and so on.</summary>
    public int Id { get; }

    /// <summary>What was found, for example "water bottle".</summary>
    public string Description { get; }

    /// <summary>Where it was found, for example "Library".</summary>
    public string Location { get; }

    /// <summary>Builds an item, refusing blank text before anything reaches the database.</summary>
    public FoundItem(int id, string description, string location)
    {
        if (string.IsNullOrWhiteSpace(description))
        {
            throw new ArgumentException("Description is required.");
        }

        if (string.IsNullOrWhiteSpace(location))
        {
            throw new ArgumentException("Location is required.");
        }

        Id = id;
        Description = description.Trim();
        Location = location.Trim();
    }

    /// <summary>Shows the item as "#1 water bottle (Library)".</summary>
    public override string ToString()
    {
        return $"#{Id} {Description} ({Location})";
    }
}
